using Microsoft.EntityFrameworkCore;

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "AppDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Session>(b =>
        {
            b.ToContainer("Sessions");

            // Fix 1: EF Core 9 changed the default discriminator property from
            // "Discriminator" to "$type". Existing documents use "Discriminator",
            // so we must explicitly preserve the old property name.
            b.HasDiscriminator<string>("Discriminator");

            // Fix 2: EF Core 9 no longer includes the discriminator in the JSON
            // `id` property. Existing documents have id = "Session|<key>".
            // Preserve the old format so existing documents remain accessible.
            b.HasRootDiscriminatorInJsonId(true);
        });
    }
}

class Session
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

// Fix 3: EF Core 9 Cosmos provider no longer supports synchronous I/O.
// All sync calls (ToList, SaveChanges, First, etc.) now throw.
// Convert to async equivalents.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (throws in EF Core 9):
    //   var sessions = _db.Sessions.Where(s => s.Name == name).ToList();
    //   _db.SaveChanges();

    // AFTER: use async equivalents
    public async Task<List<Session>> GetSessionsAsync(string name)
    {
        return await _db.Sessions
            .Where(s => s.Name == name)
            .ToListAsync();
    }

    public async Task SaveAsync()
    {
        await _db.SaveChangesAsync();
    }
}

